import {isReference, type SanityDocument} from '@sanity/types'
import omit from 'lodash-es/omit.js'

import {
  assertNotVariantVersion,
  disabledForVariantVersion,
  type VariantVersionDisabledReason,
} from '../utils/assertNotVariantVersion'
import {isLiveEditEnabled} from '../utils/isLiveEditEnabled'
import {operationsApiClient} from '../utils/operationsApiClient'
import {type OperationImpl, type PublishOptions} from './types'

function strengthenOnPublish<T>(obj: T): T {
  if (isReference(obj)) {
    if (obj._strengthenOnPublish) {
      return omit(
        obj,
        ['_strengthenOnPublish'].concat(obj._strengthenOnPublish.weak ? [] : ['_weak']),
      ) as T
    }
    return obj
  }
  if (typeof obj !== 'object' || !obj) return obj
  if (Array.isArray(obj)) return obj.map(strengthenOnPublish) as T
  return Object.fromEntries(
    Object.entries(obj).map(([key, value]) => [key, strengthenOnPublish(value)] as const),
  ) as T
}

type DisabledReason =
  | 'LIVE_EDIT_ENABLED'
  | 'ALREADY_PUBLISHED'
  | 'NO_CHANGES'
  | VariantVersionDisabledReason

export const publish: OperationImpl<[options?: PublishOptions], DisabledReason> = {
  disabled: ({schema, typeName, snapshots}) => {
    // Legacy transaction publish. Variant-scoped versions are disabled here — use
    // `serverOperations/publish.ts` instead.
    const variantDisabled = disabledForVariantVersion(snapshots?.version)
    if (variantDisabled) {
      return variantDisabled
    }
    if (isLiveEditEnabled(schema, typeName)) {
      return 'LIVE_EDIT_ENABLED'
    }
    if (!snapshots.draft && !snapshots.version) {
      return snapshots.published ? 'ALREADY_PUBLISHED' : 'NO_CHANGES'
    }
    return false
  },
  execute: ({client, idPair, snapshots}) => {
    if (!snapshots.draft && !snapshots.version) {
      throw new Error('cannot execute "publish" when draft or version is missing')
    }
    assertNotVariantVersion(snapshots.version, 'publish')

    const value = strengthenOnPublish(
      omit(snapshots.draft || snapshots.version, '_updatedAt') as SanityDocument,
    )
    const tx = operationsApiClient(client, idPair).observable.transaction()

    if (snapshots.published) {
      // If it exists already, we only want to update it if the revision on the remote server
      // matches what our local state thinks it's at
      tx.patch(idPair.publishedId, {
        // Hack until other mutations support revision locking
        unset: ['_revision_lock_pseudo_field_'],
        ifRevisionID: snapshots.published._rev,
      })

      tx.createOrReplace({
        ...value,
        _id: idPair.publishedId,
      })
    } else {
      // If the document has not been published, we want to create it - if it suddenly exists
      // before being created, we don't want to overwrite if, instead we want to yield an error
      tx.create({
        ...value,
        _id: idPair.publishedId,
      })
    }

    tx.delete(value._id)

    return tx.commit({tag: 'document.publish', visibility: 'async'})
  },
}
